parameters.jsCode:
const items = $input.all();
return items.map(item => {
  const data = item.json.body || item.json;
  const title = data.title || 'Untitled Book';
  const author = data.author || 'Unknown Author';
  const genre = data.genre || 'Uncategorized';
  const highlights = data.highlights || [];
  const notes = data.notes || '';
  const rating = data.rating || 0;
  const isbn = data.isbn || '';
  const pages = data.pages || 0;
  const dateFinished = data.dateFinished || new Date().toISOString();

  const highlightsList = Array.isArray(highlights)
    ? highlights.map((h, i) => `${i + 1}. "${typeof h === 'string' ? h : h.text || h}"${h.page ? ` (p.${h.page})` : ''}`).join('\n')
    : String(highlights);

  return {
    json: {
      title,
      author,
      genre,
      highlightsList,
      highlightCount: Array.isArray(highlights) ? highlights.length : 0,
      notes,
      rating,
      isbn,
      pages,
      dateFinished
    }
  };
});

